1	/**
2	 * CPython's `int(str)` coercion.
3	 *
4	 * Accepts surrounding Unicode whitespace, an optional sign, Unicode decimal digits
5	 * (not just ASCII) and PEP 515 underscore separators between digits. Values are
6	 * arbitrary precision, so the result is a BigInt.
7	 */
8	
9	/** Code points for which Python's Py_UNICODE_ISSPACE is true. */
10	const WHITESPACE = new Set(
11	  [
12	    0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85, 0xa0, 0x1680,
13	    0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007, 0x2008, 0x2009,
14	    0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
15	  ],
16	);
17	
18	/** Raised for input `int()` would reject; the caller turns it into an argparse error. */
19	export class PyValueError extends Error {}
20	
21	const DECIMAL_DIGIT = /\p{Nd}/u;
22	const INT_LITERAL = /^([+-]?)(\p{Nd}+(?:_\p{Nd}+)*)$/u;
23	
24	function isSpace(ch) {
25	  return WHITESPACE.has(ch.codePointAt(0));
26	}
27	
28	function strip(text) {
29	  const chars = Array.from(text);
30	  let start = 0;
31	  let end = chars.length;
32	  while (start < end && isSpace(chars[start])) start += 1;
33	  while (end > start && isSpace(chars[end - 1])) end -= 1;
34	  return chars.slice(start, end).join('');
35	}
36	
37	/**
38	 * Numeric value of a Unicode decimal digit. Unicode guarantees decimal digits come
39	 * in contiguous runs of ten starting at the script's zero, so walking backwards to
40	 * the first non-digit code point recovers the offset within the run.
41	 */
42	function decimalValue(ch) {
43	  const cp = ch.codePointAt(0);
44	  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30;
45	  for (let back = 1; back <= 10 && cp - back >= 0; back += 1) {
46	    if (!DECIMAL_DIGIT.test(String.fromCodePoint(cp - back))) return back - 1;
47	  }
48	  return 0;
49	}
50	
51	export function pyInt(text) {
52	  const match = INT_LITERAL.exec(strip(text));
53	  if (match === null) throw new PyValueError(`invalid literal for int() with base 10: ${text}`);
54	
55	  const [, sign, body] = match;
56	  let ascii = '';
57	  for (const ch of body) {
58	    if (ch !== '_') ascii += String(decimalValue(ch));
59	  }
60	  return BigInt(sign === '-' ? `-${ascii}` : ascii);
61	}
62	
63	/** `int.__name__`, used verbatim in argparse's "invalid int value" message. */
64	pyInt.pyName = 'int';
